# =============================================================================
# SCRIPT 05: FIGURES - SHORT-MEMORY SCENARIOS 1 TO 4 (SUPPLEMENTARY MATERIAL)
# =============================================================================
# Paper: Prass, T. S. and Pumi, G. (2021). On the behavior of the DFA and DCCA
#        in trend-stationary processes. Journal of Multivariate Analysis,
#        182, 104703.
#
# Reads the simulation outputs from `results/part2_scenarios/` (generated by
# Script 04), computes the exact theoretical expectations via `DCCA::rhoE()`,
# and produces the figures in Section 1 of the Supplementary Material:
#   - figures/cn1a.pdf, figures/cn1b.pdf         (Figure S1: Scenario 1)
#   - figures/cn2cor5.pdf, figures/cn2cor8.pdf,
#     figures/cn2a.pdf, figures/cn2b.pdf         (Figure S3: Scenario 2)
#   - figures/cn3a.pdf, figures/cn3b.pdf,
#     figures/cn4a.pdf, figures/cn4b.pdf         (Figure S4: Scenarios 3 & 4)
#
# Note: Updated for DCCA >= 1.0.0 (`rhoE()` returns `$F2dfa1`, `$F2dfa2`,
#       `$Fdcca`, and `$rhodcca`).
# =============================================================================

library(ggplot2)
library(ggpubr)
library(DCCA)

indir  <- "results/part2_scenarios"
outdir <- "figures"
dir.create(outdir, showWarnings = FALSE)

# =============================================================================
# Helper functions for polynomial operations and covariance matrices
# =============================================================================
polyinv.ar <- function(ar = NULL, m = 1000) {
  phi <- c(ar[-1], rep(0, m - length(ar) + 1))
  psi <- numeric(m + 1)
  psi[1] <- 1
  for (i in 2:(m + 1)) psi[i] <- -sum(rev(phi[1:(i - 1)]) * psi[1:(i - 1)])
  psi
}

poly.prod <- function(a = 1, b = 1) {
  k1 <- length(a) - 1
  k2 <- length(b) - 1
  k <- k1 + k2
  p <- numeric(k + 1)
  ax <- rep(0, k + 1); ax[1:(k1 + 1)] <- a
  bx <- rep(0, k + 1); bx[1:(k2 + 1)] <- b
  for (i in 0:k) {
    p[i + 1] <- sum(ax[1:(i + 1)] * bx[(i + 1):1])
  }
  p
}

# Builds the (m_max + 1) x (m_max + 1) autocovariance matrix from MA weights psi
cov_matrix_ma <- function(psi, m_max) {
  n_psi <- length(psi)
  acv <- sapply(0:m_max, function(h) sum(psi[1:(n_psi - h)] * psi[(1 + h):n_psi]))
  toeplitz(acv)
}

# Builds the (m_max + 1) x (m_max + 1) cross-covariance matrix when X_1 and X_2
# are driven by the same white noise through filters psi_X and psi_Y
ccv_matrix_common_innov <- function(psi_X, psi_Y, m_max) {
  G12 <- matrix(0, nrow = m_max + 1, ncol = m_max + 1)
  nX <- length(psi_X)
  nY <- length(psi_Y)
  for (t in 1:(m_max + 1)) {
    for (h in 0:(m_max + 1 - t)) {
      G12[t, t + h] <- sum(psi_X[(1 + h):nX] * psi_Y[1:(nY - h)])
      G12[t + h, t] <- sum(psi_Y[(1 + h):nY] * psi_X[1:(nX - h)])
    }
  }
  G12
}

# Builds the (m_max + 1) x (m_max + 1) upper-triangular cross-covariance matrix
# when X_2(t) = sum_{h >= 0} psi_Y[h + 1] * X_1(t - h) with X_1 ~ WN(0, 1)
ccv_matrix_unidirectional <- function(psi_Y, m_max) {
  G12 <- matrix(0, nrow = m_max + 1, ncol = m_max + 1)
  for (t in 1:(m_max + 1)) {
    for (h in 0:(m_max + 1 - t)) {
      G12[t, t + h] <- psi_Y[h + 1]
    }
  }
  G12
}

# =============================================================================
# Plotting setup and helper
# =============================================================================
My_theme <- theme_bw() +
  theme(
    text = element_text(size = rel(4), face = "bold"),
    strip.text.x = element_text(size = rel(4)),
    strip.text.y = element_text(size = rel(4))
  )

m_min <- 3
m_max <- 101
ms <- seq(m_min, m_max, 2)
dm <- length(ms)
bks <- seq(1, dm, 3)
cores <- c("blue", "red", "green", "yellow")

grph <- function(df, lbl, cor = cores[1], al = 0.6, wd = 0.4, os = 0.3,
                 ml = 1:dm, yl, cl = "red", sl = 0.5) {
  ggplot() + My_theme + xlab("m") + ylab("") + ggtitle(lbl) +
    theme(plot.title = element_text(size = 14, face = "bold")) +
    geom_boxplot(data = df, aes(x = as.factor(ind), y = values),
                 fill = cor, alpha = al, width = wd, outlier.size = os) +
    scale_x_discrete(breaks = ms[bks], labels = ms[bks]) +
    geom_line(aes(x = ml, y = yl), col = cl, linewidth = sl)
}

plot_scenario <- function(suffix, Gamma1, Gamma2, Gamma12, pdf_name) {
  E <- DCCA::rhoE(ms, G1 = Gamma1, G2 = Gamma2, G12 = Gamma12)
  read_st <- function(prefix) {
    df <- read.table(file.path(indir, paste0(prefix, suffix)), header = FALSE)
    colnames(df) <- ms
    stack(df)
  }
  p10 <- grph(df = read_st("dfa1"),    lbl = ~{F["1,DFA"]^2}(m) ~ " with " ~ nu == 0, cor = cores[1], yl = E$F2dfa1)
  p20 <- grph(df = read_st("dfa2"),    lbl = ~{F["2,DFA"]^2}(m) ~ " with " ~ nu == 0, cor = cores[2], yl = E$F2dfa2)
  p30 <- grph(df = read_st("dcca"),    lbl = ~{F[DCCA]}(m)      ~ " with " ~ nu == 0, cor = cores[3], yl = E$Fdcca)
  p40 <- grph(df = read_st("rhodcca"), lbl = ~{rho[DCCA]}(m)    ~ " with " ~ nu == 0, cor = cores[4], yl = E$rhodcca)

  pdf(file.path(outdir, pdf_name), width = 20, height = 4)
  print(ggarrange(p10, p20, p30, p40, ncol = 4, nrow = 1))
  dev.off()
}

I_m <- diag(m_max + 1)
Z_m <- matrix(0, nrow = m_max + 1, ncol = m_max + 1)

# =============================================================================
# Generate all scenario figures (Figures S1, S3, and S4)
# =============================================================================

# Scenario 1a: Two independent i.i.d. sequences -> cn1a.pdf
plot_scenario("_1.txt", I_m, I_m, Z_m, "cn1a.pdf")

# Scenario 1b: Independent AR(1) and MA(1) processes -> cn1b.pdf
psi_ar1   <- polyinv.ar(ar = c(1, -0.6), m = 1000)
theta_ma1 <- c(1, 0.6, rep(0, m_max - 1))
plot_scenario("_1_2.txt", cov_matrix_ma(psi_ar1, m_max), cov_matrix_ma(theta_ma1, m_max), Z_m, "cn1b.pdf")

# Scenario 2a: Signal plus noise (sigma_eps^2 = 4) -> cn2a.pdf
plot_scenario("_2.txt", I_m, 8 * I_m, 2 * I_m, "cn2a.pdf")

# Scenario 2b: Signal plus noise (sigma_eps^2 = 64) -> cn2b.pdf
plot_scenario("_2_2.txt", I_m, 68 * I_m, 2 * I_m, "cn2b.pdf")

# Scenario 2c: Bivariate white noise with rho = 0.5 -> cn2cor5.pdf
plot_scenario("_2_cor5.txt", I_m, I_m, 0.5 * I_m, "cn2cor5.pdf")

# Scenario 2d: Bivariate white noise with rho = 0.8 -> cn2cor8.pdf
plot_scenario("_2_cor8.txt", I_m, I_m, 0.8 * I_m, "cn2cor8.pdf")

# Scenario 3a: Cross-correlation induced by MA(20) structure -> cn3a.pdf
theta_ma20 <- c(c(1, (20:1) / 10), rep(0, m_max - 20))
plot_scenario("_3.txt", I_m, cov_matrix_ma(theta_ma20, m_max),
              ccv_matrix_unidirectional(theta_ma20, m_max), "cn3a.pdf")

# Scenario 3b: Cross-correlation induced by AR(1) structure -> cn3b.pdf
plot_scenario("_3_2.txt", I_m, cov_matrix_ma(psi_ar1, m_max),
              ccv_matrix_unidirectional(psi_ar1, m_max), "cn3b.pdf")

# Scenario 4a: Common AR(1) innovation with AR(1) filters -> cn4a.pdf
psi_X_4a <- polyinv.ar(ar = poly.prod(c(1, -0.2), c(1, -0.7)), m = 1000)
psi_Y_4a <- polyinv.ar(ar = poly.prod(c(1, -0.6), c(1, -0.7)), m = 1000)
plot_scenario("_4.txt", cov_matrix_ma(psi_X_4a, m_max), cov_matrix_ma(psi_Y_4a, m_max),
              ccv_matrix_common_innov(psi_X_4a, psi_Y_4a, m_max), "cn4a.pdf")

# Scenario 4b: Common AR(1) innovation with MA(1) filters -> cn4b.pdf
phi_inv  <- polyinv.ar(c(1, -0.7), m = 1000)
psi_X_4b <- poly.prod(phi_inv, c(1, 0.2))
psi_Y_4b <- poly.prod(phi_inv, c(1, 0.6))
plot_scenario("_4_2.txt", cov_matrix_ma(psi_X_4b, m_max), cov_matrix_ma(psi_Y_4b, m_max),
              ccv_matrix_common_innov(psi_X_4b, psi_Y_4b, m_max), "cn4b.pdf")
